# Alert Determinism Test
# Verifies that runtime alerts generated by AlertEngine match stored database flags.
import sys
import os
import sqlite3

# Add backend to python path
sys.path.append(os.path.abspath(os.path.join(os.path.dirname(__file__), "../backend")))

from app.db.session import SessionLocal
from app.db.models import ExoplanetCandidate, AgreementMetrics
from services.alert_engine import AlertEngine

def run_determinism_test():
    db = SessionLocal()
    engine = AlertEngine(db)
    
    candidates = db.query(ExoplanetCandidate).all()
    print(f"Running Alert Determinism Test on {len(candidates)} candidates...")
    
    discrepancies = 0
    
    for cand in candidates:
        # 1. Get database flag
        metrics = cand.agreement_metrics
        db_unphysical = metrics.is_unphysical_rp if metrics else False
        
        # 2. Get runtime alert
        runtime_alerts = engine.generate_alerts(cand.id)
        runtime_unphysical = any(a["category"] == "UNPHYSICAL_DERIVED_PLANET_RADIUS" for a in runtime_alerts)
        
        if db_unphysical != runtime_unphysical:
            print(f"DISCREPANCY for {cand.pl_name}: Stored is_unphysical_rp={db_unphysical}, Runtime alert={runtime_unphysical}")
            discrepancies += 1
            
    db.close()
    
    print("\n--- Alert Determinism Test Results ---")
    print(f"Total checked: {len(candidates)}")
    print(f"Total discrepancies: {discrepancies}")
    if discrepancies == 0:
        print("STATUS: PASS (100% Agreement between Database and Runtime Alert Engine)")
        sys.exit(0)
    else:
        print("STATUS: FAIL")
        sys.exit(1)

if __name__ == "__main__":
    run_determinism_test()
